<template>
  <main class="login-page"><section class="login-art"><div class="art-copy"><span class="eyebrow">门店运营管理</span><h1>让每一次<br><em>欢唱时刻</em>都值得。</h1><p>一站式管理包厢、餐品与订单，给门店一个清晰的运营视角。</p></div><div class="art-shape shape-one"></div><div class="art-shape shape-two"></div><span class="art-caption">轻松欢唱 · 简单管理</span></section><section class="login-form"><div class="form-inner"><div class="mini-brand"><span>♪</span> KTV 管理后台</div><div class="form-heading"><h2>欢迎回来</h2><p>登录后开始管理您的门店</p></div><el-form ref="formRef" :model="form" :rules="rules" @submit.prevent="submit"><el-form-item prop="username"><label>账号</label><el-input v-model="form.username" size="large" placeholder="请输入管理员账号" :prefix-icon="User" /></el-form-item><el-form-item prop="password"><label>密码</label><el-input v-model="form.password" size="large" type="password" show-password placeholder="请输入登录密码" :prefix-icon="Lock" /></el-form-item><el-button class="submit" size="large" type="primary" native-type="submit" :loading="loading">登录管理后台 <el-icon><ArrowRight /></el-icon></el-button></el-form><p class="tip">请使用已初始化的管理员账号登录</p></div><footer>© 2026 KTV 管理后台 · 安全管理中心</footer></section></main>
</template>
<script setup>
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { User, Lock, ArrowRight } from '@element-plus/icons-vue'
import { ktvLogin, ktvLogout } from '@/api/ktv'
const router = useRouter(); const loading = ref(false); const formRef = ref(); const form = reactive({ username: 'admin', password: '' }); const rules = { username: [{ required: true, message: '请输入账号', trigger: 'blur' }], password: [{ required: true, message: '请输入密码', trigger: 'blur' }] }
async function submit() { await formRef.value.validate(); loading.value = true; localStorage.removeItem('ktv-token'); localStorage.removeItem('ktv-role'); try { const { data } = await ktvLogin({ username: String(form.username || '').trim(), password: form.password }); if (data.role !== 'admin') { localStorage.setItem('ktv-token', data.token); try { await ktvLogout() } finally { localStorage.removeItem('ktv-token'); localStorage.removeItem('ktv-role') } throw new Error('后台只允许管理员账号登录') } localStorage.setItem('ktv-token', data.token); localStorage.setItem('ktv-role', 'admin'); router.replace('/ktv') } catch (error) { localStorage.removeItem('ktv-token'); localStorage.removeItem('ktv-role'); const status = error.response?.status; const message = error.response?.data?.message || error.response?.data?.msg; ElMessage.error(status === 401 || status === 403 ? (message || '账号或密码错误，请确认管理员密码') : (message || error.message || '登录失败，请检查网络连接')) } finally { loading.value = false } }
</script>
