stify-content:space-between;padding:0 17px;--el-color-primary:#d97757;--el-color-primary-dark-2:#bc5e40;border:0;border-radius:9px}.tip{color:#a0a7a1;font-size:11px;text-align:center;margin-top:20px}footer{position:absolute;bottom:28px;left:0;right:0;text-align:center;color:#b0b4ae;font-size:10px}@media(max-width:760px){.login-page{grid-template-columns:1fr}.login-art{display:none}.login-form{padding:35px 28px}.mini-brand{margin-bottom:65px}}
</style>


